document.addEventListener('DOMContentLoaded', function() {
    // Gestion mobile uniquement pour le collapse
    const isMobile = window.innerWidth <= 544;

    if (isMobile) {
        // Configuration des sections
        const sections = [
            {
                container: '#stats',
                title: 'Infos Cursus',
                hasExistingTitle: false
            },
            {
                container: '#competences',
                title: 'Compétences recherchées',
                hasExistingTitle: true
            },
            {
                container: '#formation',
                title: 'Infos pratiques',
                hasExistingTitle: false
            },
            {
                container: '#calendar',
                title: 'Calendrier',
                hasExistingTitle: true,
                isCalendar: true
            },
            {
                container: '.related.products',
                title: 'Formations Complémentaires',
                hasExistingTitle: true
            }
        ];

        sections.forEach(section => {
            const container = document.querySelector(section.container);
            if (!container) return;

            // Pour les titres existants, remplacer la classe
            if (section.hasExistingTitle) {
                const existingTitle = container.querySelector('.inset-title');
                if (existingTitle) {
                    existingTitle.classList.remove('inset-title');
                    existingTitle.classList.add('mobile-accordion-title');
                }
            } else {
                // Créer le nouveau titre s'il n'existe pas déjà
                const titleElement = document.createElement('h3');
                titleElement.textContent = section.title;
                titleElement.classList.add('mobile-accordion-title');
                container.insertBefore(titleElement, container.firstChild);
            }

            // Ajouter la classe collapsed par défaut
            container.classList.add('collapsed');

            if (section.isCalendar) {
                // Pour le calendrier, masquer uniquement les divs qui suivent
                const summary = container.closest('.summary');
                const calendarIndex = Array.from(summary.children).indexOf(container);
                Array.from(summary.children).forEach((el, index) => {
                    if (index > calendarIndex &&
                        !el.classList.contains('DOPBSPCalendar') &&
                        !el.classList.contains('DOPBSPCalendar-info-message') &&
                        el.tagName.toLowerCase() !== 'script') {
                        el.style.display = 'none';
                    }
                });
            } else {
                // Pour les autres sections
                Array.from(container.children).forEach(child => {
                    if (!child.classList.contains('mobile-accordion-title') &&
                        !child.classList.contains('inset-title')) {
                        child.style.display = 'none';
                    }
                });
            }

            // Gérer le clic sur le titre
            const titleElement = container.querySelector('.mobile-accordion-title');

            if (titleElement) {
                titleElement.addEventListener('click', () => {
                    if (section.isCalendar) {
                        // Pour le calendrier, gérer uniquement les divs qui suivent
                        const summary = container.closest('.summary');
                        const calendarIndex = Array.from(summary.children).indexOf(container);
                        container.classList.toggle('collapsed');

                        Array.from(summary.children).forEach((el, index) => {
                            if (index > calendarIndex &&
                                !el.classList.contains('DOPBSPCalendar') &&
                                !el.classList.contains('DOPBSPCalendar-info-message') &&
                                el.tagName.toLowerCase() !== 'script') {
                                el.style.display = container.classList.contains('collapsed') ? 'none' : 'block';
                            }
                        });
                    } else {
                        // Pour les autres sections
                        container.classList.toggle('collapsed');
                        Array.from(container.children).forEach(child => {
                            if (!child.classList.contains('mobile-accordion-title') &&
                                !child.classList.contains('inset-title')) {
                                child.style.display = container.classList.contains('collapsed') ? 'none' : '';
                            }
                        });
                    }
                });
            }
        });

        // Pour le calendrier, on cible uniquement les éléments qui suivent directement la div calendar
        let calendarDiv = document.querySelector('#calendar');
        if (calendarDiv) {
            let calendarContent = calendarDiv.nextElementSibling;
            if (calendarContent) {
                calendarContent.style.display = 'none';
            }
        }
    }

    // Gestion des ancres pour tous les écrans
    const handleAnchorClick = (e, targetId) => {
        e.preventDefault();
        const targetSection = document.querySelector(targetId);
        if (targetSection) {
            // Sur mobile, déployer la section si elle est repliée
            if (isMobile && targetSection.classList.contains('collapsed')) {
                const titleElement = targetSection.querySelector('.mobile-accordion-title');
                if (titleElement) {
                    titleElement.click();
                }
            }
            // Scroll vers la section
            targetSection.scrollIntoView({ behavior: 'smooth' });
        }
    };

    // Gestion des liens vers le calendrier
    const calendarLinks = document.querySelectorAll('a[href="#calendar"]');
    calendarLinks.forEach(link => {
        link.addEventListener('click', (e) => handleAnchorClick(e, '#calendar'));
    });

    // Gestion des liens vers le panier
    const cartLinks = document.querySelectorAll('a[href="#add-to-cart"]');
    cartLinks.forEach(link => {
        link.addEventListener('click', (e) => handleAnchorClick(e, '#add-to-cart'));
    });
});
